import { plugin, t } from "@api/i18n";
import { definePluginSettings } from "@api/Settings";
import { CodeBlock } from "@components/CodeBlock";
import ErrorBoundary from "@components/ErrorBoundary";
import { Heading } from "@components/Heading";
import { PcDevs } from "@utils/constants";
import { copyWithToast } from "@utils/discord";
import definePlugin, { IconComponent, OptionType } from "@utils/types";
import { ChannelStore, Modal, openModal } from "@webpack/common";

const DecodeIcon: IconComponent = ({ height = 24, width = 24, className }) => {
    return (
        <svg width={width} height={height} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
            <path d="M6.5 9.50026H14.0385C15.4063 9.50026 16.0902 9.50026 16.5859 9.82073C16.8235 9.97438 17.0259 10.1767 17.1795 10.4144C17.5 10.91 17.5 11.5939 17.5 12.9618C17.5 14.3297 17.5 15.0136 17.1795 15.5092C17.0259 15.7469 16.8235 15.9492 16.5859 16.1029C16.0902 16.4233 15.4063 16.4233 14.0385 16.4233H9.5M6.5 9.50026L8.75 7.42334M6.5 9.50026L8.75 11.5772" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" fill="none" />
        </svg>
    );
};

function isValidUtf8String(str) {
    try {
        new TextDecoder("utf-8", { fatal: true }).decode(new Uint8Array(str.split("").map(char => char.charCodeAt(0))));
        return true;
    } catch (e) {
        return false;
    }
}

function findBase64Strings(content) {
    const base64Regex = /\b[A-Za-z0-9+/]{4,}(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?\b/g;
    const matches = content.match(base64Regex);
    return matches || [];
}

function decodeBase64Strings(base64Strings) {
    return base64Strings.map(base64 => {
        try {
            const decoded = atob(base64);
            return isValidUtf8String(decoded) ? decoded : null;
        } catch (e) {
            console.error("Failed to decode base64 content:", e);
            return null;
        }
    }).filter(decoded => decoded !== null);
}

function openDecodedBase64Modal(decodedContent) {
    openModal(props => (
        <ErrorBoundary>
            <Modal
                {...props}
                size="lg"
                title={t(plugin.decodeBase64.modal.title)}
                actions={decodedContent.map((content, index) => ({
                    text: t(plugin.decodeBase64.modal.copy, { index: index + 1 }),
                    variant: "primary",
                    onClick: () => copyWithToast(content, t(plugin.decodeBase64.modal.copied))
                }))}
            >
                <div style={{ padding: "16px 0" }}>
                    <Heading>{t(plugin.decodeBase64.modal.content)}</Heading>
                    {decodedContent.map((content, index) => (
                        <CodeBlock key={index} content={content} lang="" />
                    ))}
                </div>
            </Modal>
        </ErrorBoundary>
    ));
}

const settings = definePluginSettings({
    clickMethod: {
        label: () => t(plugin.decodeBase64.option.clickMethod.label),
        description: () => t(plugin.decodeBase64.option.clickMethod.description),
        type: OptionType.SELECT,
        options: [
            { label: () => t(plugin.decodeBase64.option.clickMethod.left), value: "Left", default: true },
            { label: () => t(plugin.decodeBase64.option.clickMethod.right), value: "Right" }
        ],
    }
});

export default definePlugin({
    name: "DecodeBase64",
    description: () => t(plugin.decodeBase64.description),
    authors: [PcDevs.ThePirateStoner, PcDevs.MutanPlex],
    tags: ["chat", "utility", "developers"],
    settings,

    messagePopoverButton: {
        icon: DecodeIcon,
        render(msg) {
            const handleClick = () => {
                const base64Strings = findBase64Strings(msg.content);
                const decodedContent = decodeBase64Strings(base64Strings);
                if (settings.store.clickMethod === "Right") {
                    decodedContent.forEach(content => copyWithToast(content));
                } else {
                    openDecodedBase64Modal(decodedContent);
                }
            };

            const handleContextMenu = e => {
                const base64Strings = findBase64Strings(msg.content);
                const decodedContent = decodeBase64Strings(base64Strings);
                if (settings.store.clickMethod === "Left") {
                    e.preventDefault();
                    e.stopPropagation();
                    decodedContent.forEach(content => copyWithToast(content));
                } else {
                    e.preventDefault();
                    e.stopPropagation();
                    openDecodedBase64Modal(decodedContent);
                }
            };

            const label = settings.store.clickMethod === "Right"
                ? t(plugin.decodeBase64.right.decode)
                : t(plugin.decodeBase64.right.copy);

            return {
                label,
                icon: DecodeIcon,
                message: msg,
                channel: ChannelStore.getChannel(msg.channel_id),
                onClick: handleClick,
                onContextMenu: handleContextMenu
            };
        }
    }
});
