import "./style.css";

import { plugin, t } from "@api/i18n";
import { addMemberListDecorator, removeMemberListDecorator } from "@api/MemberListDecorators";
import { addMessageDecoration, removeMessageDecoration } from "@api/MessageDecorations";
import { addNicknameIcon, removeNicknameIcon } from "@api/NicknameIcons";
import { definePluginSettings } from "@api/Settings";
import { Devs, PcDevs } from "@utils/constants";
import definePlugin, { OptionType } from "@utils/types";

import { VoiceChannelIndicator } from "./components";

const settings = definePluginSettings({
    showInUserProfileModal: {
        label: () => t(plugin.userVoiceShow.option.showInUserProfileModal.label),
        description: () => t(plugin.userVoiceShow.option.showInUserProfileModal.description),
        type: OptionType.BOOLEAN,
        default: true,
        restartNeeded: true
    },
    showInMemberList: {
        label: () => t(plugin.userVoiceShow.option.showInMemberList.label),
        description: () => t(plugin.userVoiceShow.option.showInMemberList.description),
        type: OptionType.BOOLEAN,
        default: true,
        restartNeeded: true
    },
    showInMessages: {
        label: () => t(plugin.userVoiceShow.option.showInMessages.label),
        description: () => t(plugin.userVoiceShow.option.showInMessages.description),
        type: OptionType.BOOLEAN,
        default: true,
        restartNeeded: true
    }
});

export default definePlugin({
    name: "UserVoiceShow",
    description: () => t(plugin.userVoiceShow.description),
    authors: [Devs.Nuckyz, Devs.LordElias, PcDevs.omaw],
    tags: ["voice", "servers", "friends", "utility"],
    dependencies: ["NicknameIconsAPI", "MemberListDecoratorsAPI", "MessageDecorationsAPI"],
    settings,

    patches: [
        {
            find: "null!=this.peopleListItemRef.current",
            replacement: {
                match: /\.isProvisional.{0,50}?className:\i\.\i,children:\[(?<=isFocused:(\i).+?)/,
                replace: "$&$self.VoiceChannelIndicator({userId:this?.props?.user?.id,isActionButton:true,shouldHighlight:$1}),"
            },
            predicate: () => settings.store.showInMemberList
        }
    ],

    start() {
        if (settings.store.showInUserProfileModal) {
            addNicknameIcon("UserVoiceShow", ({ userId }) => <VoiceChannelIndicator userId={userId} isProfile />);
        }
        if (settings.store.showInMemberList) {
            addMemberListDecorator("UserVoiceShow", ({ user }) => user == null ? null : <VoiceChannelIndicator userId={user.id} />);
        }
        if (settings.store.showInMessages) {
            addMessageDecoration("UserVoiceShow", ({ message }) => message?.author == null ? null : <VoiceChannelIndicator userId={message.author.id} isMessageIndicator />);
        }
    },

    stop() {
        removeNicknameIcon("UserVoiceShow");
        removeMemberListDecorator("UserVoiceShow");
        removeMessageDecoration("UserVoiceShow");
    },

    VoiceChannelIndicator
});
