const cl = classNameFactory("pc-plugin-modal-");

const AvatarStyles = findCssClassesLazy("moreUsers", "avatar", "clickableAvatar");
const ConfirmModal = findComponentByCodeLazy('parentComponent:"ConfirmModal"');
const WarningIcon = findComponentByCodeLazy("3.15H3.29c-1.74");
const UserRecord: Constructor<Partial<User>> = proxyLazy(() => UserStore.getCurrentUser().constructor) as any;

function getName(name: string | (() => string)): string {
    return typeof name === "function" ? name() : name;
}

interface PluginModalProps extends RenderModalProps {
    plugin: Plugin;
    onRestartNeeded(key: string): void;
}

export function makeDummyUser(user: { username: string; id?: string; avatar?: string; }) {
    const newUser = new UserRecord({
        username: user.username,
        id: user.id ?? generateId(),
        avatar: user.avatar,
        /** To stop discord making unwanted requests... */
        bot: true,
    });

    FluxDispatcher.dispatch({
        type: "USER_UPDATE",
        user: newUser,
    });

    return newUser;
}

function PluginTags({ tags }: { tags: PluginTag[]; }) {
    return (
        <div className={cl("tags")}>
            {tags.map(tag => (
                <div key={tag} className={cl("tag")}>{t(pluginI18n.tags[tag])}</div>
            ))}
        </div>
    );
}

export default function PluginModal({ plugin, onRestartNeeded, onClose, transitionState }: PluginModalProps) {

    const pluginName = getName(plugin.name);
    const pluginSettings = useSettings([`plugins.${pluginName}.*`]).plugins[pluginName];
    useForceUpdateOnLocaleChange();

    const displayName = (plugin as any).displayName || pluginName;
    const rawDisplayDescription = (plugin as any).displayDescription;
    const displayDescription = rawDisplayDescription
        ? (typeof rawDisplayDescription === "function" ? rawDisplayDescription() : rawDisplayDescription)
        : (typeof plugin.description === "function" ? plugin.description() : plugin.description);

    const hasSettings = hasAnyVisibleSettings(plugin);
    // avoid layout shift by showing dummy users while loading users
    const fallbackAuthors = useMemo(() => [makeDummyUser({ username: t(plugins.loading), id: "-1465912127305809920" })], []);
    const [authors, setAuthors] = useState<Partial<User>[]>([]);

    useEffect(() => {
        (async () => {
            for (const [index, user] of plugin.authors.slice(0, 6).entries()) {
                try {
                    const author = user.id
                        ? await UserUtils.getUser(String(user.id))
                            .catch(() => makeDummyUser({ username: user.name }))
                        : makeDummyUser({ username: user.name });

                    setAuthors(a => [...a, author]);
                } catch (e) {
                    continue;
                }
            }
        })();
    }, [plugin.authors]);

    function handleResetClick() {
        openWarningModal(plugin, onRestartNeeded);
    }

    function renderSettings() {
        const { settings } = plugin;
        if (!hasSettings || !settings)
            return <Paragraph>{t(plugins.pluginModal.noSettings)}</Paragraph>;

        const options = Object.entries(settings.def).map(([key, setting]) => {
            if (setting.type === OptionType.CUSTOM) return null;

            if (isSettingHidden(settings, setting)) return null;

            function onChange(newValue: any) {
                const option = plugin.settings!.def[key];
                if (!option || option.type === OptionType.CUSTOM) return;

                pluginSettings[key] = newValue;

                if (option.restartNeeded) onRestartNeeded(key);
            }

            const Component = OptionComponentMap[setting.type];
            return (
                <ErrorBoundary noop key={key}>
                    <Component
                        id={key}
                        setting={setting}
                        onChange={debounce(onChange)}
                        pluginSettings={pluginSettings}
                        definedSettings={settings}
                        closePluginSettings={onClose}
                    />
                </ErrorBoundary>
            );
        });

        return (
            <div className="pc-plugins-settings">
                {options}
            </div>
        );
    }

    function renderMoreUsers(_label: string) {
        const remainingAuthors = plugin.authors.slice(6);

        return (
            <Tooltip text={remainingAuthors.map(u => u.name).join(", ")}>
                {({ onMouseEnter, onMouseLeave }) => (
                    <div
                        className={AvatarStyles.moreUsers}
                        onMouseEnter={onMouseEnter}
                        onMouseLeave={onMouseLeave}
                    >
                        +{remainingAuthors.length}
                    </div>
                )}
            </Tooltip>
        );
    }

    const pluginMeta = PluginMeta[pluginName];

    return (
        <Modal
            transitionState={transitionState}
            onClose={onClose}
            size="lg"
            title={
                <div className={cl("header")}>
                    <BaseText tag="h1" size="lg" weight="semibold" className={cl("title")}>{displayName}</BaseText>
                    {!pluginMeta.userPlugin && (
                        <div className={cl("links")}>
                            <FavoriteButton
                                isFavorite={pluginSettings.isFavorite ?? false}
                                onClick={() => pluginSettings.isFavorite = !pluginSettings.isFavorite}
                            />
                            <WebsiteButton
                                text={t(plugins.pluginModal.info)}
                                href={`https://plexcord.club/plugins/${plugin.name}`}
                            />
                            <GithubButton
                                text={t(plugins.pluginModal.source)}
                                href={`https://github.com/${gitRemote}/tree/main/src/plugins/${pluginMeta.folderName}`}
                            />
                        </div>
                    )}
                </div>
            }
            subtitle={
                <div className={cl("info")}>
                    <div>
                        <BaseText size="sm" className={cl("description")}>{displayDescription}</BaseText>
                        {!!plugin.tags?.length && <PluginTags tags={plugin.tags} />}
                    </div>
                </div>
            }
        >
            {!!plugin.settingsAboutComponent && (
                <div className={classes(Margins.top16, cl("about-box"))}>
                    <section>
                        <ErrorBoundary message={t(plugins.error.infoRender)}>
                            <plugin.settingsAboutComponent />
                        </ErrorBoundary>
                    </section>
                </div>
            )}
            <div className="pc-settings-modal-content">
                <section>
                    <BaseText size="lg" weight="semibold" color="text-strong" className={classes(Margins.top8, Margins.bottom8)}>{t(plugins.pluginModal.authors)}</BaseText>
                    <div style={{ width: "fit-content" }}>
                        <ErrorBoundary noop>
                            <UserSummaryItem
                                users={authors.length ? authors : fallbackAuthors}
                                guildId={undefined}
                                renderIcon={false}
                                showDefaultAvatarsForNullUsers
                                renderMoreUsers={renderMoreUsers}
                                renderUser={(user: User) => (
                                    <Clickable
                                        className={AvatarStyles.clickableAvatar}
                                        onClick={() => openContributorModal(user)}
                                    >
                                        <img
                                            className={AvatarStyles.avatar}
                                            src={user.getAvatarURL(void 0, 80, true)}
                                            alt={user.username}
                                            title={user.username}
                                        />
                                    </Clickable>
                                )}
                            />
                        </ErrorBoundary>
                    </div>
                </section>

                <section>
                    <Flex style={{ justifyContent: "space-between", alignItems: "center" }} className={classes(Margins.top16, Margins.bottom8)}>
                        <BaseText size="lg" weight="semibold" color="text-strong">{t(plugins.pluginModal.settings)}</BaseText>
                        {hasSettings && (
                            <Tooltip text={t(plugins.restart.resetDefault)} shouldShow={!isObjectEmpty(pluginSettings)}>
                                {({ onMouseEnter, onMouseLeave }) => (
                                    <Button
                                        variant="dangerPrimary"
                                        size="small"
                                        onClick={handleResetClick}
                                        onMouseEnter={onMouseEnter}
                                        onMouseLeave={onMouseLeave}
                                    >
                                        {t(plugins.restart.button.reset)}
                                    </Button>
                                )}
                            </Tooltip>
                        )}
                    </Flex>
                    {renderSettings()}
                </section>
            </div>
        </Modal>
    );
}

export function openPluginModal(plugin: Plugin, onRestartNeeded?: (pluginName: string, key: string) => void) {
    const pluginName = getName(plugin.name);
    openModal(modalProps => (
        <PluginModal
            {...modalProps}
            plugin={plugin}
            onRestartNeeded={(key: string) => onRestartNeeded?.(pluginName, key)}
        />
    ));
}

function resetSettings(plugin: Plugin, onRestartNeeded?: (pluginName: string) => void) {
    const defaultSettings = plugin.settings?.def;
    const pluginName = getName(plugin.name);

    if (!defaultSettings) return;

    const newSettings: Record<string, any> = {};
    let restartNeeded = false;

    for (const key in defaultSettings) {
        if (key === "enabled") continue;

        const setting = defaultSettings[key];
        setting.type = setting.type ?? OptionType.STRING;

        if (setting.type === OptionType.STRING) {
            newSettings[key] = setting.default !== undefined && setting.default !== "" ? setting.default : "";
        } else if ("default" in setting && setting.default !== undefined) {
            newSettings[key] = setting.default;
        }

        if (setting?.restartNeeded) {
            restartNeeded = true;
        }
    }

    const currentSettings = plugin.settings?.store;
    if (currentSettings) {
        Object.assign(currentSettings, newSettings);
    }

    if (restartNeeded) {
        onRestartNeeded?.(pluginName);
    }

    showToast({
        text: t(plugins.pluginModal.successfulReset, { plugin: pluginName }),
        variant: "success",
        position: "top"
    });
}

export function openWarningModal(plugin?: Plugin | null, onRestartNeeded?: (pluginName: string) => void, isPlugin = true, enabledPlugins?: number | null, reset?: () => void) {
    openModal(props => (
        <ConfirmModal
            {...props}
            className={cl("confirm")}
            header={isPlugin ? t(plugins.dangerModal.resetSettings) : t(plugins.dangerModal.disablePlugins)}
            confirmText={isPlugin ? t(plugins.dangerModal.resetText) : t(plugins.dangerModal.disableText)}
            cancelText={t(plugins.dangerModal.cancel)}
            onConfirm={() => {
                if (isPlugin && plugin) {
                    resetSettings(plugin, onRestartNeeded);
                } else {
                    reset?.();
                }
            }}
            onCancel={props.onClose}
        >
            <Paragraph>
                {isPlugin
                    ? t(plugins.dangerModal.resetDescription, { pluginName: <strong>{plugin ? getName(plugin.name) : ""}</strong> })
                    : t(plugins.dangerModal.disable, { enabledPlugins: <strong>{enabledPlugins}</strong> })
                }
            </Paragraph>
            <div className={classes(Margins.top16, cl("warning"))}>
                <WarningIcon color="var(--text-feedback-critical)" />
                <span>{t(plugins.dangerModal.undone)}</span>
            </div>
        </ConfirmModal>
    ));
}
