import { plugin, t } from "@api/i18n";
import { Heading } from "@components/Heading";
import { RenderModalProps } from "@plexcord/discord-types";
import { DEFAULT_COLOR, SWATCHES } from "@plugins/pinDms/constants";
import { categoryLen, createCategory, getCategory } from "@plugins/pinDms/data";
import { classNameFactory } from "@utils/css";
import { extractAndLoadChunksLazy, findComponentByCodeLazy } from "@webpack";
import { ColorPicker, Modal, openModalLazy, TextInput, useMemo, useState } from "@webpack/common";

interface ColorPickerWithSwatchesProps {
    className?: string;
    defaultColor: number;
    colors: number[];
    value: number;
    disabled?: boolean;
    onChange(value: number | null): void;
    renderDefaultButton?: () => React.ReactNode;
    renderCustomButton?: () => React.ReactNode;
}

const ColorPickerWithSwatches = findComponentByCodeLazy<ColorPickerWithSwatchesProps>('id:"color-picker"');

export const requireSettingsModal = extractAndLoadChunksLazy(['type:"USER_SETTINGS_MODAL_OPEN"']);

const cl = classNameFactory("pc-pindms-modal-");

interface Props {
    categoryId: string | null;
    initialChannelId: string | null;
    modalProps: RenderModalProps;
}

function useCategory(categoryId: string | null, initalChannelId: string | null) {
    const category = useMemo(() => {
        if (categoryId) {
            return getCategory(categoryId);
        } else if (initalChannelId) {
            return {
                id: crypto.randomUUID(),
                name: t(plugin.pinDMs.modal.defaultCategoryName, { number: categoryLen() + 1 }),
                color: DEFAULT_COLOR,
                collapsed: false,
                channels: [initalChannelId]
            };
        }
    }, [categoryId, initalChannelId]);

    return category;
}

export function NewCategoryModal({ categoryId, modalProps, initialChannelId }: Props) {
    const category = useCategory(categoryId, initialChannelId);

    const [name, setName] = useState(category?.name ?? "");
    const [color, setColor] = useState(category?.color ?? DEFAULT_COLOR);

    if (!category) return null;

    const onSave = () => {
        category.name = name;
        category.color = color;

        if (!categoryId) {
            createCategory(category);
        }

        modalProps.onClose();
    };

    return (
        <Modal
            {...modalProps}
            title={categoryId ? t(plugin.pinDMs.modal.category.edit) : t(plugin.pinDMs.modal.category.new)}
            actions={[{
                text: categoryId ? t(plugin.pinDMs.modal.category.save) : t(plugin.pinDMs.modal.category.create),
                variant: "primary",
                onClick: onSave,
                disabled: !name
            }]}
        >
            {/* form is here so when you press enter while in the text input it submits */}
            <form
                className={cl("content")}
                onSubmit={e => {
                    e.preventDefault();
                    onSave();
                }}
            >
                <section>
                    <Heading tag="h5">{t(plugin.pinDMs.modal.category.name)}</Heading>
                    <TextInput
                        value={name}
                        onChange={e => setName(e)}
                    />
                </section>
                <section>
                    <Heading tag="h5">{t(plugin.pinDMs.modal.category.color)}</Heading>
                    <ColorPickerWithSwatches
                        className={cl("color-picker")}
                        key={category.id}
                        defaultColor={DEFAULT_COLOR}
                        colors={SWATCHES}
                        onChange={c => setColor(c!)}
                        value={color}
                        renderDefaultButton={() => null}
                        renderCustomButton={() => (
                            <ColorPicker
                                color={color}
                                onChange={c => setColor(c!)}
                                key={category.id}
                                showEyeDropper={false}
                            />
                        )}
                    />
                </section>
            </form>
        </Modal>
    );
}

export const openCategoryModal = (categoryId: string | null, channelId: string | null) =>
    openModalLazy(async () => {
        await requireSettingsModal();
        return modalProps => <NewCategoryModal categoryId={categoryId} modalProps={modalProps} initialChannelId={channelId} />;
    });
