import { commands as commandsI18n, i18n, t } from "@api/i18n";
import { CommandArgument, CommandContext, CommandOption } from "@plexcord/discord-types";
import { Logger } from "@utils/Logger";
import { makeCodeblock } from "@utils/text";

import { sendBotMessage } from "./commandHelpers";
import { ApplicationCommandInputType, ApplicationCommandOptionType, ApplicationCommandType, PlexcordCommand } from "./types";

export * from "./commandHelpers";
export * from "./types";

export let BUILT_IN: PlexcordCommand[];
export const commands = {} as Record<string, PlexcordCommand>;

// hack for plugins being evaluated before we can grab these from webpack
const OptPlaceholder = Symbol("OptionalMessageOption") as any as CommandOption;
const ReqPlaceholder = Symbol("RequiredMessageOption") as any as CommandOption;

/**
 * Optional message option named "message" you can use in commands.
 * Used in "tableflip" or "shrug"
 * @see {@link RequiredMessageOption}
 */
export let OptionalMessageOption: CommandOption = OptPlaceholder;
/**
 * Required message option named "message" you can use in commands.
 * Used in "me"
 * @see {@link OptionalMessageOption}
 */
export let RequiredMessageOption: CommandOption = ReqPlaceholder;

let idCounter = 99;

export const _init = function (cmds: PlexcordCommand[]) {
    try {
        BUILT_IN = cmds;
        OptionalMessageOption = cmds.find(c => (c.untranslatedName || c.displayName) === "shrug")!.options![0];
        RequiredMessageOption = cmds.find(c => (c.untranslatedName || c.displayName) === "me")!.options![0];
        idCounter = Math.abs(BUILT_IN.map(x => Number(x.id)).sort((x, y) => x - y)[0]) + 1;

        try {
            i18n.addListener(() => {
                updateCommandTranslations();
            });
        } catch (e) {
            new Logger("CommandsAPI").warn("Failed to set up i18n listener:", e);
        }
    } catch (e) {
        new Logger("CommandsAPI").error("Failed to load CommandsApi", e, " - cmds is", cmds);
    }
    return cmds;
} as never;

export const _handleCommand = function (cmd: PlexcordCommand, args: CommandArgument[], ctx: CommandContext) {
    if (!cmd.isPlexcordCommand)
        return cmd.execute(args, ctx);

    const handleError = (err: any) => {
        // TODO: cancel send if cmd.inputType === BUILT_IN_TEXT
        const msg = `An Error occurred while executing command "${cmd.name}"`;
        const reason = err instanceof Error ? err.stack || err.message : String(err);
        const msgErr = t(commandsI18n.error.execute, { command: cmd.name });
        console.error(msg, err);
        sendBotMessage(ctx.channel.id, {
            author: {
                username: "Plexcord"
            },
            content: `${msgErr}:\n${makeCodeblock(reason)}`
        });
    };

    try {
        const res = cmd.execute(args, ctx);
        return res instanceof Promise ? res.catch(handleError) : res;
    } catch (err) {
        return handleError(err);
    }
} as never;

/**
 * Prepare a Command Option for Discord by filling missing fields
 * @param opt
 */
export function prepareOption<O extends CommandOption | PlexcordCommand>(opt: O): O {
    opt.displayName ||= opt.name;
    opt.displayDescription ||= typeof opt.description === "function" ? opt.description() : opt.description;
    opt.options?.forEach((opt, i, opts) => {
        // See comment above Placeholders
        if (opt === OptPlaceholder) opts[i] = OptionalMessageOption;
        else if (opt === ReqPlaceholder) opts[i] = RequiredMessageOption;
        opt.choices?.forEach(x => x.displayName ||= x.name);

        prepareOption(opts[i]);
    });
    return opt;
}

export function updateCommandTranslations() {
    if (!BUILT_IN) return;

    BUILT_IN.forEach(cmd => {
        if (cmd.isPlexcordCommand) {
            if (typeof cmd.displayDescription === "undefined" && cmd.untranslatedDescription) {
                try {
                    const translatedDescription = t(cmd.untranslatedDescription as any);
                    if (translatedDescription !== cmd.untranslatedDescription) {
                        cmd.displayDescription = translatedDescription;
                    }
                } catch {
                    // If translation fails, keep the original
                }
            }

            if (typeof cmd.displayName === "undefined" && cmd.untranslatedName) {
                try {
                    const translatedName = t(cmd.untranslatedName as any);
                    if (translatedName !== cmd.untranslatedName) {
                        cmd.displayName = translatedName;
                    }
                } catch {
                    // If translation fails, keep the original
                }
            }
        }
    });
}

const isSubCommandParent = (cmd: PlexcordCommand) => cmd.options?.[0]?.type === ApplicationCommandOptionType.SUB_COMMAND;
const getSubCommandName = (cmd: PlexcordCommand, option: CommandOption) => `${cmd.name} ${option.name}`;

// Yes, Discord registers individual commands for each subcommand
function registerSubCommands(cmd: PlexcordCommand, plugin: string) {
    cmd.options?.forEach(o => {
        if (o.type !== ApplicationCommandOptionType.SUB_COMMAND)
            throw new Error("When specifying sub-command options, all options must be sub-commands.");

        const subCmd = {
            ...cmd,
            ...o,
            options: o.options !== undefined ? o.options : undefined,
            type: ApplicationCommandType.CHAT_INPUT,
            id: `${o.name}-${cmd.id}`,
            name: getSubCommandName(cmd, o),
            displayName: getSubCommandName(cmd, o),
            subCommandPath: [{
                name: o.name,
                type: o.type,
                displayName: o.name
            }],
            rootCommand: cmd
        };
        registerCommand(subCmd, plugin);
    });
}

function unregisterSubCommands(cmd: PlexcordCommand): boolean {
    const results = BUILT_IN
        .filter(c => c.rootCommand === cmd)
        .map(c => unregisterCommand(c.name));

    return results.length > 0 && results.every(x => x);
}

export function registerCommand<C extends PlexcordCommand>(command: C, plugin: string) {
    if (!BUILT_IN) {
        console.warn(
            "[CommandsAPI]",
            `Not registering ${command.name} as the CommandsAPI hasn't been initialised.`,
            "Please restart to use commands"
        );
        return;
    }

    if (BUILT_IN.some(c => c.name === command.name))
        throw new Error(`Command '${command.name}' already exists.`);

    command.isPlexcordCommand = true;
    command.untranslatedName ??= command.name;
    command.untranslatedDescription ??= typeof command.description === "function" ? command.description() : command.description;
    command.id ??= `-${idCounter++}`;
    command.applicationId ??= "-1"; // BUILT_IN;
    command.type ??= ApplicationCommandType.CHAT_INPUT;
    command.inputType ??= ApplicationCommandInputType.BUILT_IN_TEXT;
    command.plugin ||= plugin;

    prepareOption(command);
    commands[command.name] = command;

    if (isSubCommandParent(command)) {
        registerSubCommands(command, plugin);
        return;
    }

    BUILT_IN.push(command);
}

export function unregisterCommand(name: string, isSubCommands = false) {
    const cmd = commands[name];
    if (cmd && isSubCommandParent(cmd)) {
        delete commands[name];
        return unregisterSubCommands(cmd);
    }

    const idx = BUILT_IN.findIndex(c => c.name === name);
    if (idx === -1)
        return false;

    BUILT_IN.splice(idx, 1);
    delete commands[name];

    return true;
}
