import { plugin, t } from "@api/i18n";
import { BaseText } from "@components/BaseText";
import { Flex } from "@components/Flex";
import { LinkIcon } from "@components/Icons";
import { Link } from "@components/Link";
import { apiConstants } from "@plugins/songSpotlight.desktop/lib/api";
import { useSongStore } from "@plugins/songSpotlight.desktop/lib/stores/SongStore";
import { cl, formatCoverTooltip, formatDurationMs } from "@plugins/songSpotlight.desktop/lib/utils";
import { Native, useRender } from "@plugins/songSpotlight.desktop/service";
import {
    CardClasses,
    ExplicitTag,
    ImageBrokenIcon,
    OverlayClasses,
    PlayButton,
    PuzzlePieceIcon,
    TrashIcon,
} from "@plugins/songSpotlight.desktop/ui/common";
import AudioPlayer from "@plugins/songSpotlight.desktop/ui/components/AudioPlayer";
import ProgressCircle from "@plugins/songSpotlight.desktop/ui/components/ProgressCircle";
import ServiceIcon from "@plugins/songSpotlight.desktop/ui/components/ServiceIcon";
import { openSettingsModal } from "@plugins/songSpotlight.desktop/ui/settings";
import { RenderInfoEntry, RenderInfoEntryBased, RenderSongInfo } from "@song-spotlight/api/handlers";
import { Song as SongType } from "@song-spotlight/api/structs";
import { isListLayout, sid } from "@song-spotlight/api/util";
import { copyWithToast } from "@utils/discord";
import { classes } from "@utils/misc";
import { Clickable, ContextMenuApi, FluxDispatcher, Menu, React, ScrollerThin, showToast, Tooltip, useCallback, useMemo, useRef, useState } from "@webpack/common";

interface SongEntryProps {
    entry: RenderInfoEntryBased;
    number: string;
    isLoaded: boolean;
    isPlaying: boolean;
    big?: boolean;
    onClick(): void;
}

function SongEntry({ entry, number, isLoaded, isPlaying, big, onClick }: SongEntryProps) {
    const baseSize = big ? "md" : "sm";
    const subSize = big ? "sm" : "xs";

    return (
        <Clickable
            onContextMenu={e =>
                ContextMenuApi.openContextMenu(e, () => (
                    <Menu.Menu
                        navId="pc-songspotlight-song-entry"
                        onClose={() => FluxDispatcher.dispatch({ type: "CONTEXT_MENU_CLOSE" })}
                        aria-label={entry.label}
                    >
                        <Menu.MenuItem
                            id="copy-link"
                            label={t(plugin.songSpotlight.text.copyLink)}
                            icon={LinkIcon}
                            leadingAccessory={{ type: "icon", icon: LinkIcon }}
                            action={() => copyWithToast(entry.link)}
                        />
                        <Menu.MenuItem
                            id="steal-song"
                            label={t(plugin.songSpotlight.text.stealSong)}
                            icon={PuzzlePieceIcon}
                            leadingAccessory={{ type: "icon", icon: PuzzlePieceIcon }}
                            action={async () => {
                                const self = useSongStore.getState().self?.data ?? [];
                                if (self.length >= apiConstants.songLimit) {
                                    return showToast({ text: t(plugin.songSpotlight.toast.youDonTHave) });
                                }

                                const song = await Native.parseLink(entry.link);
                                if (!song) {
                                    return showToast({ text: t(plugin.songSpotlight.toast.uhOhThisSong), variant: "critical" });
                                }

                                if (self.find(x => sid(x) === sid(song))) {
                                    return showToast({ text: t(plugin.songSpotlight.toast.youAlreadyHaveThis) });
                                }

                                openSettingsModal([...self, song]);
                            }}
                        />
                    </Menu.Menu>
                ))}
            onClick={onClick}
        >
            <Flex
                alignItems="center"
                gap="4px"
                className={cl("song-entry")}
                aria-disabled={!isLoaded}
                data-playing={isPlaying}
            >
                <Flex alignItems="center" justifyContent="center" gap={0} className={cl("song-entry-number")}>
                    <BaseText size={baseSize} weight="medium">{number}</BaseText>
                </Flex>
                <Flex flexDirection="column" justifyContent="center" gap={0}>
                    <Flex alignItems="center" gap="6px">
                        <BaseText size={subSize} weight="semibold" className={cl("clamped")} title={entry.label}>
                            {entry.label}
                        </BaseText>
                        {entry.explicit && <ExplicitTag />}
                    </Flex>
                    <BaseText size={subSize} weight="normal" className={cl("clamped", "sub")} title={entry.sublabel}>
                        {entry.sublabel}
                    </BaseText>
                </Flex>
            </Flex>
        </Clickable>
    );
}

interface SongInfoProps {
    owned: boolean;
    song: SongType;
    render: RenderSongInfo;
    big?: boolean;
}

function SongInfo({ owned, song, render, big }: SongInfoProps) {
    const [playing, setPlaying] = useState<number | undefined>(undefined);
    const [loaded, setLoaded] = useState(new Set<number>());
    const setLoadedAudio = useCallback((index: number, state: boolean) => {
        if (state) loaded.add(index);
        else loaded.delete(index);
        setLoaded(new Set(loaded));
    }, [loaded]);

    const audios = useMemo(() => render.form === "single" ? [render.single] : render.list, [render]);
    const audioRef = useRef<HTMLAudioElement>(undefined);
    const playingRef = useRef<RenderInfoEntry>(undefined);
    playingRef.current = playing !== undefined ? audios[playing] : undefined;

    const duration = useMemo(
        () =>
            render.form === "single" ?
                render.single.audio?.duration :
                playing !== undefined ?
                    render.list[playing].audio?.duration :
                    undefined,
        [playing, render],
    );

    const baseSize = big ? "md" : "sm";
    const subSize = big ? "sm" : "xs";

    return (
        <Flex flexDirection="column" gap={0} className={cl("song")}>
            <AudioPlayer
                audioRef={audioRef}
                list={audios}
                playing={playing}
                setPlaying={setPlaying}
                setLoadedAudio={setLoadedAudio}
            />
            <div className={cl("song-grid")}>
                <Flex gap="8px" alignItems="center" className={cl("song-core")}>
                    <Tooltip text={formatCoverTooltip(song, render)}>
                        {props => (
                            <Flex
                                {...props}
                                onContextMenu={e =>
                                    ContextMenuApi.openContextMenu(e, () => (
                                        <Menu.Menu
                                            navId="pc-songspotlight-song"
                                            onClose={() => FluxDispatcher.dispatch({ type: "CONTEXT_MENU_CLOSE" })}
                                            aria-label={render.label}
                                        >
                                            <Menu.MenuItem
                                                id="copy-link"
                                                label={t(plugin.songSpotlight.text.copyLink)}
                                                icon={LinkIcon}
                                                leadingAccessory={{ type: "icon", icon: LinkIcon }}
                                                action={() => copyWithToast(render.link)}
                                            />
                                            {!owned
                                                ? (
                                                    <Menu.MenuItem
                                                        id="steal-song"
                                                        label={t(plugin.songSpotlight.text.stealSong)}
                                                        icon={PuzzlePieceIcon}
                                                        leadingAccessory={{ type: "icon", icon: PuzzlePieceIcon }}
                                                        action={() => {
                                                            const self = useSongStore.getState().self?.data ?? [];
                                                            if (self.length >= apiConstants.songLimit) {
                                                                return showToast({ text: t(plugin.songSpotlight.toast.youDonTHave) });
                                                            }
                                                            if (self.find(x => sid(x) === sid(song))) {
                                                                return showToast({ text: t(plugin.songSpotlight.toast.youAlreadyHaveThis) });
                                                            }

                                                            openSettingsModal([...self, song]);
                                                        }}
                                                    />
                                                )
                                                : (
                                                    <Menu.MenuItem
                                                        id="remove-song"
                                                        color="danger"
                                                        label={t(plugin.songSpotlight.text.removeSong)}
                                                        icon={TrashIcon}
                                                        leadingAccessory={{ type: "icon", icon: TrashIcon }}
                                                        action={() => {
                                                            const self = useSongStore.getState().self?.data ?? [];

                                                            const i = self.findIndex(x => sid(x) === sid(song));
                                                            if (i === -1) {
                                                                return showToast({ text: t(plugin.songSpotlight.toast.youDonTHave2) });
                                                            }

                                                            openSettingsModal(self.toSpliced(i, 1));
                                                        }}
                                                    />
                                                )}
                                        </Menu.Menu>
                                    ))}
                                justifyContent="center"
                                alignItems="center"
                                gap={0}
                                className={cl("song-cover")}
                            >
                                <Link href={render.link} style={{ display: "contents" }}>
                                    {render.thumbnailUrl
                                        ? <img src={render.thumbnailUrl} alt={render.label} />
                                        : (
                                            <ImageBrokenIcon
                                                className={cl("icon")}
                                            />
                                        )}
                                </Link>
                            </Flex>
                        )}
                    </Tooltip>
                    <Flex
                        flexDirection="column"
                        justifyContent="center"
                        gap={0}
                        className={cl("clamped")}
                    >
                        <Flex alignItems="center" gap="6px">
                            <BaseText size={baseSize} weight="semibold" className={cl("clamped")} title={render.label}>
                                {render.label}
                            </BaseText>
                            {render.explicit && <ExplicitTag />}
                        </Flex>
                        <BaseText
                            size={baseSize}
                            weight="normal"
                            className={cl("clamped", "sub")}
                            title={render.sublabel}
                        >
                            {render.sublabel}
                        </BaseText>
                    </Flex>
                </Flex>
                <Flex justifyContent="flex-end" className={cl("song-service")}>
                    <ServiceIcon service={song.service} />
                </Flex>
                <Flex
                    justifyContent="flex-end"
                    alignItems="flex-end"
                    gap="6px"
                    className={cl("song-player")}
                    data-idle={playing === undefined && !big}
                >
                    {duration && (
                        <BaseText size={subSize} weight="medium" className={cl("mono", "sub")}>
                            {formatDurationMs(duration)}
                        </BaseText>
                    )}
                    <div className={cl("song-progress-container")}>
                        <ProgressCircle
                            border={2.5}
                            playingRef={playingRef}
                            audioRef={audioRef}
                            className={cl("song-progress")}
                        />
                        <PlayButton
                            state={playing !== undefined}
                            disabled={loaded.size < 1}
                            onClick={() => {
                                if (playing !== undefined) return setPlaying(undefined);

                                const loadedIndex = loaded.values().toArray().sort()[0];
                                if (loadedIndex !== undefined) setPlaying(loadedIndex);
                            }}
                        />
                    </div>
                </Flex>
            </div>
            {render.form === "list" && (
                <>
                    <div className={cl("song-divider")} />
                    <ScrollerThin fade className={cl("song-list")}>
                        <Flex flexDirection="column" gap="3px">
                            {render.list.map((entry, i) => (
                                <SongEntry
                                    entry={entry}
                                    number={(i + 1).toString()}
                                    isLoaded={loaded.has(i)}
                                    isPlaying={playing === i}
                                    onClick={() => {
                                        if (playing === i) setPlaying(undefined);
                                        else if (loaded.has(i)) setPlaying(i);
                                    }}
                                    big={big}
                                    key={entry.link}
                                />
                            ))}
                        </Flex>
                    </ScrollerThin>
                </>
            )}
        </Flex>
    );
}

interface SongInfoContainerProps {
    owned: boolean;
    song: SongType;
    index: number;
    big?: boolean;
}

export default function Song({ owned, song, index, big }: SongInfoContainerProps) {
    const { failed, render } = useRender(song);

    if (failed) return null;

    return (
        <div
            className={classes(
                OverlayClasses.overlay,
                CardClasses.card,
                cl("song-container", {
                    "list-song-container": isListLayout(song, render || undefined),
                }),
            )}
            style={{
                ["--index" as any]: index.toString(),
            }}
        >
            {render && <SongInfo owned={owned} song={song} render={render} big={big} />}
        </div>
    );
}
